//! `memref` generated by `mlirformat tblgen` (`memref.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "memref.gen.rs"]
mod memref;

#[test]
fn memref_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<memref::Memref>();
    common::Fixtures::check_dialect(&opt, "memref");
}
